// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'silviagomessgm-oss/meridiano-motor',
  github_rama: 'main',
  supabase_url: 'https://vxvmgwlrtrhqjuacmdss.supabase.co',
  hoja_datos_id: '1qXWmguY7LEdKcJPN2aKaWtKEmj9cY_l7SGqDC9-V_ko',
  panel_url: 'https://meridiano-press.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',
  modelo_ia: 'claude-sonnet-5-5',
  modo_demo: true,
  buzon_demo: 'meridiano.pres@gmail.com',
} }];

// Flujo de los lunes: la fecha de la semana es el lunes de hoy (si se ejecuta otro día, el lunes de esta semana).
// Para una ejecución manual de prueba, cambiar por: return [{ json: { fecha: '2026-11-02' } }];
const ahora = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const atras = (ahora.getDay() + 6) % 7;                         // 0 si hoy es lunes
const lunes = new Date(Date.UTC(ahora.getFullYear(), ahora.getMonth(), ahora.getDate() - atras));
return [{ json: { fecha: lunes.toISOString().slice(0, 10) } }];

// Balance de los lunes: un item por comercial con los HECHOS ya redactados (cifras formateadas). La IA solo puede usar
// las cifras de este texto, y el mismo texto va en el correo: lo que comenta la IA es comprobable por el comercial.
const r = $input.first().json || {};
if ((r.statusCode || 200) >= 300) {
  const b = r.body || {};
  throw new Error('Supabase no ha podido calcular el balance: ' + (b.message || JSON.stringify(b)).slice(0, 300));
}
const miles = n => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const eur = n => miles(n) + ' €';
const pct = t => (Number(t) * 100).toFixed(1).replace('.', ',') + ' %';
const fecha = s => { const [a, m, d] = String(s).slice(0, 10).split('-'); return `${d}/${m}`; };
const NOMBRE = { riesgo: 'riesgo', ampliacion: 'ampliación', lead_nuevo: 'lead nuevo', seguimiento: 'seguimiento' };
return (Array.isArray(r.body) ? r.body : []).map(b => {
  const s = b.semana_anterior || {}, pv = b.prevision || {}, ra = b.riesgo_abiertas || {}, t = pv.tasas_historicas || {};
  const pend = Object.entries(b.pendientes || {});
  const totalPend = pend.reduce((a, [, n]) => a + n, 0);
  const seg = b.seguimientos_debidos || [];
  const balance = [
    `Semana del ${fecha(s.desde)} al ${fecha(s.hasta)}: ${s.aceptadas} propuestas aceptadas, ${s.rechazadas} rechazadas, ` +
      `${s.enviadas} correos enviados y ${s.respuestas} respuestas registradas.`,
    `Cierres: ${s.ganadas} ganadas y ${s.perdidas} perdidas; en churn, ${s.riesgo_cerradas} cuentas cerradas, ${s.riesgo_recuperadas} recuperadas.`,
    `Leads nuevos asignados la semana pasada: ${b.leads_nuevos_semana}.`,
  ];
  const semana = [
    `Pendientes de aprobar: ${totalPend}` + (pend.length ? ` (${pend.map(([e, n]) => `${NOMBRE[e] || e} ${n}`).join(', ')})` : '') +
      `; ${b.nuevas_hoy} preparadas esta mañana. Mañana llegan las cuentas en riesgo de la semana.`,
    `En seguimiento: ${b.en_seguimiento}; piden un toque esta semana: ${seg.length}.`,
    ...seg.slice(0, 8).map(x => `  - ${x.razon_social}: ${x.dias} días desde el envío, ${x.toque}`),
    `Cuentas en riesgo aún abiertas: ${ra.cuentas} (${eur(ra.facturacion_en_riesgo_eur)} de facturación en riesgo).`,
  ];
  const prevision = [
    `${pv.propuestas_abiertas || 0} propuestas abiertas de ampliación y leads por ${eur(pv.importe_propuesto_eur)}; ` +
      `valor esperado: ${eur(pv.valor_esperado_eur)}.`,
    `Cálculo: importe propuesto × tasa histórica de éxito (ampliación ${pct(t.ampliacion || 0)}, lead nuevo ${pct(t.lead_nuevo || 0)}).`,
  ];
  const hechos = ['BALANCE', ...balance, '', 'ESTA SEMANA', ...semana, '', 'PREVISIÓN', ...prevision].join('\n');
  return { json: { id_comercial: b.id_comercial, nombre: b.nombre, correo: b.correo, hechos,
                   semana: `${fecha(s.desde)}–${fecha(s.hasta)}`, pendientes: totalPend, seguimientos: seg.length } };
});

// Sensor de Govern para el comentario de la IA: solo cifras que estén en los hechos, máximo 70 palabras.
// Si no pasa, el correo sale sin comentario (los hechos siempre van).
const filas = $('Hechos por comercial').all();
const numeros = s => new Set(String(s || '').match(/\d+(?:[.,]\d+)*/g) || []);
return $input.all().map((it, i) => {
  const f = filas[i].json, r = it.json || {};
  const texto = Array.isArray(r.content) ? r.content.filter(c => c.type === 'text').map(c => c.text).join(' ').trim() : '';
  const motivos = [];
  if (!texto) motivos.push('IA no disponible');
  else {
    const ctx = numeros(f.hechos);
    const inventadas = [...numeros(texto)].filter(n => !ctx.has(n));
    if (inventadas.length) motivos.push(`cifras no trazables [${inventadas.join(', ')}]`);
    const palabras = texto.split(/\s+/).filter(Boolean).length;
    if (palabras > 70) motivos.push(`${palabras} palabras`);
  }
  return { json: { ...f, comentario: motivos.length ? '' : texto, comentario_descartado: motivos.join('; ') } };
});

// Correo de los lunes a cada comercial: comentario de la IA (si pasó el validador) + hechos + enlace al panel.
const panel = $('Configuración').first().json.panel_url;
return $input.all().map(it => {
  const f = it.json;
  const nombre = String(f.nombre || '').split(' ')[0];
  return { json: { ...f,
    asunto: `Meridiano · tu semana: ${f.pendientes} propuestas por aprobar y ${f.seguimientos} seguimientos`,
    texto: `Hola, ${nombre}:\n\n` + (f.comentario ? f.comentario + '\n\n' : '') + f.hechos +
      `\n\nTodo se aprueba, corrige o rechaza en el panel:\n${panel}\n\n` +
      `Correo interno. No se ha enviado nada a ningún anunciante.` +
      (f.comentario ? '\n(El comentario inicial lo redacta la IA solo con las cifras de este correo.)' : ''),
  } };
});

// Resumen semanal para DIRECCIÓN: todas las acciones de la semana anterior, por comercial y en total, con lo pendiente,
// las cuentas en riesgo abiertas y la previsión. Mismos datos que reciben los comerciales (balance_lunes), sin IA:
// es un informe de hechos para supervisar, no una recomendación.
const r = $('Supabase: balance').first().json || {};
const filas = Array.isArray(r.body) ? r.body : [];
const panel = $('Configuración').first().json.panel_url;
const miles = n => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const eur = n => miles(n) + ' €';
const fecha = s => { const [a, m, d] = String(s || '').slice(0, 10).split('-'); return `${d}/${m}`; };
const suma = f => filas.reduce((a, b) => a + (Number(f(b)) || 0), 0);
const sa = b => b.semana_anterior || {};
const pend = b => Object.values(b.pendientes || {}).reduce((a, n) => a + n, 0);
const s0 = sa(filas[0] || {});
const linea = (nombre, f) =>
  `${nombre}: ${f.aceptadas} aceptadas, ${f.rechazadas} rechazadas, ${f.enviadas} enviadas, ${f.respuestas} respuestas; ` +
  `${f.ganadas} ganadas y ${f.perdidas} perdidas; churn: ${f.riesgo_cerradas} cerradas, ${f.riesgo_recuperadas} recuperadas.`;
const total = {};
for (const k of ['aceptadas', 'rechazadas', 'enviadas', 'respuestas', 'ganadas', 'perdidas', 'riesgo_cerradas', 'riesgo_recuperadas'])
  total[k] = suma(b => sa(b)[k]);
const texto = [
  `Resumen comercial de la semana del ${fecha(s0.desde)} al ${fecha(s0.hasta)}.`, '',
  'ACCIONES DE LA SEMANA',
  linea('Equipo', total),
  ...filas.map(b => '  - ' + linea(b.nombre, sa(b))), '',
  'ESTA SEMANA',
  `Pendientes de aprobar: ${suma(pend)} · en seguimiento: ${suma(b => b.en_seguimiento)} · ` +
    `piden un toque: ${suma(b => (b.seguimientos_debidos || []).length)} · leads nuevos la semana pasada: ${suma(b => b.leads_nuevos_semana)}.`,
  ...filas.map(b => `  - ${b.nombre}: ${pend(b)} pendientes, ${b.en_seguimiento} en seguimiento, ` +
    `${(b.seguimientos_debidos || []).length} toques, ${(b.riesgo_abiertas || {}).cuentas || 0} cuentas en riesgo abiertas`),
  `Cuentas en riesgo abiertas: ${suma(b => (b.riesgo_abiertas || {}).cuentas)} ` +
    `(${eur(suma(b => (b.riesgo_abiertas || {}).facturacion_en_riesgo_eur))} de facturación en riesgo).`, '',
  'PREVISIÓN',
  `${suma(b => (b.prevision || {}).propuestas_abiertas)} propuestas abiertas de ampliación y leads por ` +
    `${eur(suma(b => (b.prevision || {}).importe_propuesto_eur))}; valor esperado: ${eur(suma(b => (b.prevision || {}).valor_esperado_eur))} ` +
    '(importe × tasa histórica de éxito por origen).', '',
  `Detalle, alertas e indicadores en el panel (vista de Dirección):\n${panel}`,
].join('\n');
return [{ json: { asunto: `Meridiano · resumen comercial de la semana del ${fecha(s0.desde)}: ${total.aceptadas} aceptadas, ${total.ganadas} ganadas`,
                  texto, comerciales: filas.length } }];

// H6 · Escalado a dirección en el resumen de los lunes: seguimientos cuyo toque lleva 7 días vencido sin respuesta del
// cliente ni toque registrado (vista seguimientos_sin_atender; el grupo de control del piloto queda fuera) y el KPI de
// seguimientos al día por grupo del piloto. Se añade al resumen de dirección; si Supabase falla, se dice en el correo.
const base = $('Resumen para dirección').first().json || {};
const leer = nombre => {
  const n = $(nombre);
  const r = (n.isExecuted && n.first().json) || {};
  return r.statusCode >= 200 && r.statusCode < 300 && Array.isArray(r.body) ? r.body : null;
};
const sin = leer('Supabase: seguimientos sin atender');
const kpi = leer('Supabase: KPI de toques');
const dudosos = (() => { try { return leer('Supabase: envíos sin confirmar'); } catch (e) { return null; } })();
const conAviso = (() => { try { return leer('Supabase: aprobadas con aviso'); } catch (e) { return null; } })();
const fecha = s => { const [a, m, d] = String(s || '').slice(0, 10).split('-'); return `${d}/${m}`; };
const NOMBRE = { riesgo: 'riesgo', ampliacion: 'ampliación', lead_nuevo: 'lead nuevo', seguimiento: 'seguimiento' };

const lineas = ['', 'ESCALADO: SEGUIMIENTOS SIN ATENDER (toque vencido hace 7 días o más, sin actividad registrada)'];
if (!sin) lineas.push('No se ha podido consultar (Supabase no ha respondido). Revíselo en el panel.');
else if (!sin.length) lineas.push('Ninguno: todos los toques debidos están atendidos.');
else {
  const porCom = {};
  for (const s of sin) (porCom[s.comercial_nombre || s.comercial_asignado] ||= []).push(s);
  for (const [com, l] of Object.entries(porCom)) {
    lineas.push(`${com}: ${l.length}`);
    for (const s of l.slice(0, 10))
      lineas.push(s.fase === 'inicio'
        ? `  - ${s.razon_social} (${NOMBRE[s.etiqueta] || s.etiqueta}, llamada): aprobada el ${fecha(s.dia_envio)} y aún sin ` +
          `ninguna llamada registrada (${s.dias_vencido} días de retraso)`
        : `  - ${s.razon_social} (${NOMBRE[s.etiqueta] || s.etiqueta}, ${s.canal}): toque del día ${s.toque_debido} ` +
          `vencido hace ${s.dias_vencido} días; enviada el ${fecha(s.enviada_en)}` +
          (s.ultima_actividad ? `, última actividad el ${fecha(s.ultima_actividad)}` : ', sin actividad desde el envío'));
    if (l.length > 10) lineas.push(`  … y ${l.length - 10} más en el panel`);
  }
}
if (dudosos && dudosos.length) {
  lineas.push('', 'ENVÍOS SIN CONFIRMAR (Gmail no confirmó ni rechazó; comprobar Enviados y liberar con liberar_envio)');
  for (const d of dudosos) lineas.push(`  - Propuesta ${d.id} · ${d.razon_social} · reservada el ${fecha(d.envio_reservado_en)}`);
}
if (conAviso && conAviso.length) {
  lineas.push('', 'APROBADAS CON AVISO DEL VALIDADOR (últimos 7 días; revisar el texto con el comercial)');
  for (const a of conAviso) lineas.push(`  - ${a.comercial_nombre || a.comercial_asignado} · ${a.razon_social} · ` +
    `${[].concat(a.avisos || []).join(', ')} · aprobada el ${fecha(a.aprobada_en)}`);
}
if (kpi && kpi.length) {
  lineas.push('', 'SEGUIMIENTOS AL DÍA POR GRUPO DEL PILOTO (propuestas con algún toque debido)');
  const grupos = {};
  for (const k of kpi) { const g = (grupos[k.grupo] ||= { d: 0, a: 0 }); g.d += Number(k.con_toque_debido) || 0; g.a += Number(k.al_dia) || 0; }
  for (const [g, v] of Object.entries(grupos))
    lineas.push(`  - ${g}: ${v.a} de ${v.d} al día (${v.d ? (100 * v.a / v.d).toFixed(1).replace('.', ',') : '0,0'} %)`);
  lineas.push('  El grupo de control no recibe avisos: su porcentaje es la referencia sin el sistema.');
}
const n = sin ? sin.length : null;
return [{ json: { ...base,
  asunto: base.asunto + (n ? ` · ${n} seguimiento${n === 1 ? '' : 's'} sin atender` : ''),
  texto: String(base.texto || '').includes('\n\nDetalle, alertas e indicadores')
    ? String(base.texto).replace('\n\nDetalle, alertas e indicadores', lineas.join('\n') + '\n\nDetalle, alertas e indicadores')
    : String(base.texto || '') + '\n' + lineas.join('\n'),
  seguimientos_sin_atender: n,
} }];
